import re, pathlib
changed=[]
for p in pathlib.Path('.').rglob('*.py'):
    if p.as_posix()=='svc/api.py': continue
    s=p.read_text(); n=s
    n=re.sub(r'\blegacy_fetch\(', 'fetch_v2(', n)
    n=re.sub(r'^(from svc\.api import )legacy_fetch$', r'\1fetch_v2', n, flags=re.M)
    if n!=s: p.write_text(n); changed.append(str(p))
    for i,l in enumerate(n.splitlines(),1):
        if 'legacy_fetch' in l: print('remaining',p,i,l)
print(sorted(changed))

